from pathlib import Path
import hashlib,base64,gzip,json
p=Path('.release-v791')
parts=[(p/f'part{i}.b64').read_text().strip() for i in range(4)]
expected=['f2c6d36acf2a064adaf2e2fc660fbc6a4d9e798e6b12fa6087dbab48915ac92f','4052142b4f8289131046eda6f445961e6286afedf27b2d89eecee8265951824e','d53e4305017b04eb5c71d94efbf6178c26d4c11f7310f4abd5f4c7f10baca919','586a44a11702f2ddbbd1c501d6ffb3779e9c1e2630978bc2af53d432748af11f']
assert [hashlib.sha256(x.encode()).hexdigest() for x in parts]==expected
insert=''
parts[2]=parts[2][:2137]+insert+parts[2][2137:]
parts[2]=parts[2][:1005]+'OBi'+parts[2][1008:]
suffix=''
parts[3]=parts[3][:4595]+suffix
raw=base64.b64decode(''.join(parts),validate=True)
assert hashlib.sha256(raw).hexdigest()=='d0e5e0f7b29892f488bd9fff7b04647e919f825f52205b950bcf89a13bce6d13', 'Transport checksum mismatch: no execution permitted'
files=json.loads(gzip.decompress(raw))
allow={'assets/audit-data-v7-9-1.js','tools/prepare-operations-v7-9-1.py','tools/build-current-v7-9-1.py','tools/build-geo-v7-9-1.py','tools/export-current-v7-9-1.cjs','tools/prepare-release-v7-9-1.py','tools/test-ui-v7-9-1.mjs','tools/verify-production-v7-9-1.py'}
assert set(files)==allow
for name,content in files.items():
 target=Path(name);assert not target.exists(),name
 target.write_text(content,encoding='utf-8')
 print(name,hashlib.sha256(content.encode()).hexdigest())
print('Eight readable preparation sources restored; whole-payload SHA256 verified.')
